{"content":"import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/data/data.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';


import '../mocks/datasource.mocks.dart';

void main() {
  final MockRestDatasource mockRestDatasource = MockRestDatasource();
  final MockDbDatasource mockDbDatasource = MockDbDatasource();
  final MockPreferenceDatasource mockPreferenceDatasource = MockPreferenceDatasource();

  group('CurrencyRepository', () {
    late CurrencyRepository repository;

    setUp(() {
      repository = CurrencyRepositoryImpl(mockRestDatasource, mockDbDatasource);
    });

    test('should return correct currency list when getCurrencyList is called', () async {
      final currencyList = [
        CurrencyModel(
          id: '1',
          nominal: 1,
          name: 'Доллар США',
          symbol: 'USD',
          value: 78.4181,
          previousValue: 78.5,
        ),
        CurrencyModel(
          id: '2',
          nominal: 1,
          name: 'Евро',
          symbol: 'EUR',
          value: 92.7440,
          previousValue: 92.2,
        ),
      ];

      when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => currencyList);

      final result = await repository.getCurrencyList();

      expect(result, currencyList);
      verify(mockRestDatasource.getCurrencyList()).called(1);
    });

    test('fetchRates returns requested page and hasMore flag', () async {
      final all = [
        for (int i = 0; i < 3; i++)
          CurrencyModel(id: '$i', nominal: 1, name: 'Валюта $i', symbol: 'C$i', value: i + 1.0, previousValue: i.toDouble()),
      ];
      when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => all);

      final page0 = await repository.fetchRates(const CurrencyPageRequest(page: 0, pageSize: 2));

      expect(page0.items.map((c) => c.id), ['0', '1']);
      expect(page0.hasMore, isTrue);
    });

    test('fetchRates returns empty page beyond the end', () async {
      when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => const []);

      final page = await repository.fetchRates(const CurrencyPageRequest(page: 5, pageSize: 20));

      expect(page.items, isEmpty);
      expect(page.hasMore, isFalse);
    });

    test('should complete successfully when saveCurrencyList is called', () async {
      final currencyList = [
        CurrencyModel(
          id: '1',
          nominal: 1,
          name: 'Юань',
          symbol: 'CNY',
          value: 10.9384,
          previousValue: 10.9112,
        ),
      ];

      await repository.saveCurrencyList(currencyList);

      verify(mockDbDatasource.saveCurrencyList(currencyList)).called(1);
    });
  });

  group('NewsRepository', () {
    late NewsRepository repository;

    setUp(() {
      repository = NewsRepositoryImpl(mockRestDatasource, mockDbDatasource);
    });

    test('should return news list when getNewsList is called', () async {
      final newsList = [
        for (int i = 0; i < 3; i++)
          NewsModel(title: 'Заголовок $i', link: 'https://example.com/$i', date: DateTime.now()),
      ];

      when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);

      final result = await repository.getNewsList();

      expect(result, newsList);
      verify(mockRestDatasource.getNewsList()).called(1);
    });

    test('loadNewsFeed with forceRefresh reads from network and caches', () async {
      final newsList = [
        NewsModel(title: 'Свежая новость', link: 'https://example.com/fresh', date: DateTime.now()),
      ];
      when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);

      final result = await repository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));

      expect(result, newsList);
      verify(mockRestDatasource.getNewsList()).called(1);
      verify(mockDbDatasource.saveNewsList(newsList)).called(1);
      verifyNever(mockDbDatasource.getNewsList());
    });

    test('loadNewsFeed without forceRefresh reads only from cache', () async {
      final cached = [
        NewsModel(title: 'Из кэша', link: 'https://example.com/cached', date: DateTime.now()),
      ];
      when(mockDbDatasource.getNewsList()).thenAnswer((_) async => cached);

      final result = await repository.loadNewsFeed(NewsFeedFilter.all);

      expect(result, cached);
      verify(mockDbDatasource.getNewsList()).called(1);
      verifyNever(mockRestDatasource.getNewsList());
    });

